type RententionProcessor struct {
	processorMap map[string]thrift.TProcessorFunction
	handler      Rentention
}

func (p *RententionProcessor) AddToProcessorMap(key string, processor thrift.TProcessorFunction) {
	p.processorMap[key] = processor
}

func (p *RententionProcessor) GetProcessorFunction(key string) (processor thrift.TProcessorFunction, ok bool) {
	processor, ok = p.processorMap[key]
	return processor, ok
}

func (p *RententionProcessor) ProcessorMap() map[string]thrift.TProcessorFunction {
	return p.processorMap
}

func NewRententionProcessor(handler Rentention) *RententionProcessor {
	self := &RententionProcessor{handler: handler, processorMap: make(map[string]thrift.TProcessorFunction)}
	self.AddToProcessorMap("OverviewRender", &rententionProcessorOverviewRender{handler: handler})
	self.AddToProcessorMap("ToolsRender", &rententionProcessorToolsRender{handler: handler})
	self.AddToProcessorMap("Auth", &rententionProcessorAuth{handler: handler})
	self.AddToProcessorMap("SystemRealtimeScore", &rententionProcessorSystemRealtimeScore{handler: handler})
	self.AddToProcessorMap("SystemDailyScore", &rententionProcessorSystemDailyScore{handler: handler})
	self.AddToProcessorMap("SystemDailyApiFailureInfo", &rententionProcessorSystemDailyApiFailureInfo{handler: handler})
	self.AddToProcessorMap("SystemDailyApiFailureDetail", &rententionProcessorSystemDailyApiFailureDetail{handler: handler})
	self.AddToProcessorMap("SystemDailyApiSlowInfo", &rententionProcessorSystemDailyApiSlowInfo{handler: handler})
	self.AddToProcessorMap("SystemDailyApiCost", &rententionProcessorSystemDailyApiCost{handler: handler})
	self.AddToProcessorMap("SystemProbeLogDetail", &rententionProcessorSystemProbeLogDetail{handler: handler})
	self.AddToProcessorMap("SystemEndToEndTraceLogs", &rententionProcessorSystemEndToEndTraceLogs{handler: handler})
	self.AddToProcessorMap("SystemEndToEndUserTraceLogs", &rententionProcessorSystemEndToEndUserTraceLogs{handler: handler})
	self.AddToProcessorMap("SysteTracebackLogs", &rententionProcessorSysteTracebackLogs{handler: handler})
	self.AddToProcessorMap("RequestTrends", &rententionProcessorRequestTrends{handler: handler})
	self.AddToProcessorMap("SystemDbTidy", &rententionProcessorSystemDbTidy{handler: handler})
	self.AddToProcessorMap("SystemDbRefresh", &rententionProcessorSystemDbRefresh{handler: handler})
	self.AddToProcessorMap("GetUInfo", &rententionProcessorGetUInfo{handler: handler})
	self.AddToProcessorMap("UserActionInfo", &rententionProcessorUserActionInfo{handler: handler})
	self.AddToProcessorMap("GetOnlineOperation", &rententionProcessorGetOnlineOperation{handler: handler})
	self.AddToProcessorMap("UploadOnlineOperation", &rententionProcessorUploadOnlineOperation{handler: handler})
	self.AddToProcessorMap("WriteProbeLogs", &rententionProcessorWriteProbeLogs{handler: handler})
	return self
}
func (p *RententionProcessor) Process(ctx context.Context, iprot, oprot thrift.TProtocol) (success bool, err thrift.TException) {
	name, _, seqId, err := iprot.ReadMessageBegin()
	if err != nil {
		return false, err
	}
	if processor, ok := p.GetProcessorFunction(name); ok {
		return processor.Process(ctx, seqId, iprot, oprot)
	}
	iprot.Skip(thrift.STRUCT)
	iprot.ReadMessageEnd()
	x := thrift.NewTApplicationException(thrift.UNKNOWN_METHOD, "Unknown function "+name)
	oprot.WriteMessageBegin(name, thrift.EXCEPTION, seqId)
	x.Write(oprot)
	oprot.WriteMessageEnd()
	oprot.Flush(ctx)
	return false, x
}

